(() => {
  const byId=id=>document.getElementById(id);
  document.querySelectorAll('a[href^="#"]:not(.subsection-link)').forEach(link=>link.addEventListener('click',event=>{const target=byId(link.getAttribute('href').slice(1));if(!target)return;event.preventDefault();target.scrollIntoView({block:'start',behavior:'instant'});}));
  // Align a shared subsection URL after the initial page layout has settled.
  (() => {
    const initialHash=window.location.hash;
    const target=byId(initialHash.slice(1));
    const link=target?.matches('h3')?target.querySelector(':scope > a.subsection-link'):null;
    if(!initialHash || link?.getAttribute('href')!==initialHash)return;
    let cancelled=false;
    const events=['pointerdown','wheel','keydown','touchstart','hashchange'];
    const cleanup=()=>events.forEach(type=>window.removeEventListener(type,cancel,true));
    const cancel=()=>{cancelled=true;cleanup();};
    events.forEach(type=>window.addEventListener(type,cancel,{capture:true,passive:true}));
    const settle=()=>Promise.resolve(document.fonts?.ready).then(()=>
      requestAnimationFrame(()=>requestAnimationFrame(()=>{
        if(!cancelled && window.location.hash===initialHash && target.isConnected)target.scrollIntoView({block:'start',behavior:'instant'});
        cleanup();
      })));
    if(document.readyState==='complete')settle();
    else window.addEventListener('load',settle,{once:true});
  })();
  document.querySelectorAll('[data-jump]').forEach(button=>button.addEventListener('click',()=>{const target=byId(button.dataset.jump);if(target)target.scrollIntoView({block:'start',behavior:'instant'});if(button.dataset.jump==='top'){const contents=document.querySelector('.exposition-sidebar');if(contents)contents.scrollTop=0;}}));
  const listen=(id,fn)=>{const el=byId(id);if(el){el.addEventListener('input',fn);fn();}};
  listen('rectangle-h',()=>{const h=Number(byId('rectangle-h').value),n=100*h;byId('rectangle-h-value').textContent=h.toFixed(2);byId('rect-strip-a').setAttribute('width',n);byId('rect-strip-b').setAttribute('y',115-n);byId('rect-strip-b').setAttribute('height',n);byId('rect-corner').setAttribute('y',115-n);byId('rect-corner').setAttribute('height',n);byId('rect-corner').setAttribute('width',n);byId('rect-top-label').setAttribute('y',115-n/2+5);byId('rect-top-label').style.display=h>.12?'':'none';byId('rect-right-label').setAttribute('x',405+n);byId('rect-right-label').style.display=h>.02?'':'none';byId('rect-corner-label').setAttribute('x',405+n);byId('rect-corner-label').setAttribute('y',115-n/2+5);byId('rect-corner-label').style.display=h>.02?'':'none';byId('rect-linear').textContent=(5*h).toFixed(2);byId('rect-error').textContent=(h*h).toFixed(4);byId('rect-exact').textContent=(5*h+h*h).toFixed(4);});
  const toggle=byId('boundary-toggle');if(toggle)toggle.addEventListener('click',()=>{const show=toggle.getAttribute('aria-pressed')!=='true';toggle.setAttribute('aria-pressed',String(show));byId('boundary-signs').style.display=show?'':'none';toggle.textContent=show?'Hide endpoint signs':'Show endpoint signs';});
  listen('prime-choice',()=>{const p=Number(byId('prime-choice').value),split=p===5||p===13;byId('prime-split').style.display=split?'':'none';byId('prime-inert').style.display=p===3?'':'none';byId('prime-double').style.display=p===2?'':'none';const roots=p===13?[5,8]:[2,3];byId('prime-left-root').textContent=String(roots[0]);byId('prime-right-root').textContent=String(roots[1]);const descriptions={5:'The algebra is F₅ × F₅. The two factors are separable and the relative differential module is zero.',13:'The algebra is F₁₃ × F₁₃, with roots 5 and 8. The relative differential module is zero.',3:'The algebra is F₉. One closed point has degree 2; over an algebraic closure there are two distinct points. The relative differential module is zero.',2:'The algebra is F₂[u]/(u²). Its point has length 2 and a nonzero nilpotent direction. Its relative differential module is free of rank one, generated by du.'};byId('prime-description').textContent=descriptions[p];});
  listen('frobenius-order',()=>{const m=Number(byId('frobenius-order').value);byId('frobenius-order-value').textContent=String(m);byId('frobenius-basis').querySelectorAll('[data-degree]').forEach(cell=>{cell.classList.toggle('discarded',Number(cell.dataset.degree)>m);cell.classList.toggle('survives',Number(cell.dataset.degree)===3&&m>=3);});byId('frobenius-output').textContent=m<3?'0':'ε³';});
  const drawNode=()=>{const a=Number(byId('node-a').value),b=Number(byId('node-b').value);byId('node-a-value').textContent=a.toFixed(2);byId('node-b-value').textContent=b.toFixed(2);byId('node-direction').setAttribute('d','M300 145L'+(300+100*a)+' '+(145-100*b));byId('node-point').setAttribute('cx',300+100*a);byId('node-point').setAttribute('cy',145-100*b);byId('node-residual').textContent=(a*b).toFixed(4);byId('node-status').textContent=a*b===0?'Second-order lift exists':'Second-order lift obstructed';};listen('node-a',drawNode);listen('node-b',drawNode);
  listen('probe-order',()=>{const m=Number(byId('probe-order').value);byId('probe-order-value').textContent=String(m);byId('probe-basis').querySelectorAll('[data-degree]').forEach(cell=>cell.classList.toggle('discarded',Number(cell.dataset.degree)>m));byId('square-status').textContent=m<2?'Relation satisfied; residual 0':'Relation fails; residual ε²';byId('cube-status').textContent=m<3?'Relation satisfied; residual 0':'Relation fails; residual ε³';});
})();
